/* @lc app=leetcode id=2458 lang=kotlin */ class Solution { fun treeQueries(root: TreeNode?, queries: IntArray): IntArray = generateSequence(listOf(root!!)) { f -> f.flatMap { listOfNotNull(it.left, it.right) }.takeIf { it.isNotEmpty() } }.toList().let { levels -> HashMap<Int, Int>().let { md -> HashMap<Int, Int>().let { res -> levels.indices.reversed().forEach { d -> levels[d].forEach { n -> md[n.`val`] = maxOf(d, n.left?.let { md[it.`val`] } ?: 0, n.right?.let { md[it.`val`] } ?: 0) } }.let { levels.indices.forEach { d -> levels[d].map { md[it.`val`]!! }.sortedDescending().let { s -> levels[d].forEach { n -> res[n.`val`] = maxOf(d - 1, if (md[n.`val`] == s[0]) (if (s.size > 1) s[1] else -1) else s[0]) } } } }.let { queries.map { res[it]!! }.toIntArray() } } } } }